def _format_locations(entries: list[BlueprintEntry]) -> str:
    seen: set[tuple[str, int]] = set()
    pieces: list[str] = []
    for entry in entries:
        location = (entry.file, entry.line)
        if location in seen:
            continue
        seen.add(location)
        pieces.append(f"{entry.file}:{entry.line}")
    return ", ".join(pieces)


